using System;
using UnityEngine;
namespace Veilbound.Editor {
 public static class LibraryValidation {
  static void Check(bool ok,string text){if(!ok)throw new Exception("Library: "+text);}
  public static Settlement Sample(){var c=Settlement.NewCamp();c.EnsureResearch();c.timber=2;c.quarry=c.mine=c.weaver=c.huntersLodge=c.blacksmith=1;c.library=1;c.EnsureIndustry();c.wood=c.stone=1000000;for(int f=0;f<3;f++)for(int i=0;i<Settlement.ResourceNames[f].Length;i++)c.AddResource(f,i,100000);for(int i=0;i<WeaponRules.Count;i++)c.metalBars[i]=100000;for(int family=4;family<6;family++)for(int i=0;i<5;i++)c.AddResource(family,i,100000);return c;}
  public static void Run(){
   var boot=Settlement.NewCamp();boot.EnsureResearch();Check(boot.ResearchRank("timber")==2&&boot.ResearchRank("housing")==0,"starting entitlements");Check(!boot.StartResearch("mine",out _),"library required");
   boot.wood=boot.stone=1000;Check(boot.UpgradeBuilding("timber",out _)&&boot.timber==2,"lumbermill bootstrap stays immediate");Check(boot.UpgradeBuilding("quarry",out _)&&boot.quarry==1,"quarry bootstrap");foreach(string id in new[]{"mine","hunters","weaver","blacksmith","clothier"})Check(boot.UpgradeBuilding(id,out _)&&boot.BuildingLevel(id)==1,"starter building needs no library: "+id);
   Check(boot.MakeBars(0,1,out _)==false,"tin refining still requires ore");boot.AddResource(0,0,10);Check(boot.MakeBars(0,4,out _),"tin refining needs no library");boot.TickSmithOrders(boot.SmithQueueHours());boot.AddResource(1,0,4);boot.AddResource(2,0,4);Check(boot.UpgradeBuilding("library",out _)&&boot.library==1,"bootstrap can build Library from obtainable ingredients");
   var c=Sample();string initial=JsonUtility.ToJson(c);Check(!c.UpgradeBuilding("mine",out _)&&JsonUtility.ToJson(c)==initial,"research gate charges no building materials");Check(c.StartResearch("mine",out _)&&c.ResearchRank("mine")==1,"research starts without instant unlock");double paid=c.wood;Check(!c.StartResearch("weaver",out _)&&c.wood==paid,"one research at a time and no duplicate charge");c.Tick(720,1);Check(Math.Abs(c.researchRemaining-12)<1e-8&&c.ResearchRank("mine")==1,"halfway progress");
   c=JsonUtility.FromJson<Settlement>(JsonUtility.ToJson(c));c.EnsureResearch();Check(Math.Abs(c.researchRemaining-12)<1e-8,"remaining time survives save");c.Tick(360,2);Check(c.ResearchRank("mine")==2&&c.mine==1&&c.ResearchRank("weaver")==1,"time dilation completes independent research without constructing upgrade");
   Check(c.UpgradeBuilding("mine",out _)&&c.mine==1&&c.activeConstruction=="mine","researched upgrade starts construction");Check(!c.UpgradeBuilding("quarry",out _),"one construction queue");c.Tick(1440,1);Check(c.mine==2&&c.activeConstruction=="","construction activates new capacity at completion");
   c=Sample();double w=c.wood,s=c.stone,b=c.metalBars[0];Check(c.StartResearch("weapons",out _)&&c.CancelResearch()&&!c.CancelResearch(),"cancel research once");Check(c.wood==w&&c.stone==s&&c.metalBars[0]==b,"cancel refunds exact paid materials");
   c=Sample();Check(c.StartResearch("housing",out _),"housing research available");c.Tick(1440,1);Check(c.UpgradeBuilding("housing",out _),"housing starts construction");w=c.wood;s=c.stone;b=c.ResourceAmount(2,0);Check(c.CancelConstruction()&&c.housingTier==0&&!c.CancelConstruction(),"cancel construction before effects");Check(c.wood==w+10&&c.stone==s+5&&c.ResourceAmount(2,0)==b+4,"construction refund exact");
   c=Sample();c.StartResearch("housing",out _);c.Tick(1440,1);c.UpgradeBuilding("housing",out _);c.StartResearch("mine",out _);w=c.wood;double rate=c.WoodRate;c.Tick(2160,1);Check(c.housingTier==1&&c.ResearchRank("mine")==2&&Math.Abs(c.wood-w-rate*(24+12*1.2))<1e-7,"parallel completions split production exactly at city-hour boundary");
   var big=Sample();big.StartResearch("housing",out _);big.Tick(1440,1);big.UpgradeBuilding("housing",out _);var stepped=JsonUtility.FromJson<Settlement>(JsonUtility.ToJson(big));big.Tick(2160,1);for(int i=0;i<21600;i++)stepped.Tick(.1,1);Check(Math.Abs(big.wood-stepped.wood)<1e-5&&big.housingTier==stepped.housingTier,"one large tick agrees with frame ticks");
   c=Sample();c.blacksmith=10;w=c.metalBars[1];Check(!c.CraftMetalWeapon(1,out _)&&c.metalBars[1]==w,"copper weapon cannot bypass weapon research");Check(!c.CraftPlate(2,1,out _),"armour branch independent");Check(!c.MakeBars(1,1,out _),"refining branch independent");Check(c.StartResearch("weapons",out _),"weapon research starts");c.Tick(1440,1);Check(c.CraftMetalWeapon(1,out _)&&!c.CraftPlate(2,1,out _),"weapon research unlocks weapons only");
   var legacy=new Settlement{blacksmith=9,mine=7,weaver=5,quarry=4,housingTier=3,wood=888.125,stone=444.25};legacy.EnsureGear();legacy.EnsureResearch();Check(legacy.ResearchRank("weapons")==10&&legacy.ResearchRank("plate")==10&&legacy.ResearchRank("mine")==7&&legacy.ResearchRank("housing")==3&&legacy.wood==888.125,"legacy unlocks and stock preserved including Veilcrystal");
   Debug.Log("VEILBOUND_LIBRARY_LOGIC_PASS");
  }
 }
}
